import{_ as l,o as i,f as e,a6 as r}from"./chunks/framework.BFhbG0o2.js";const _=JSON.parse('{"title":"AI 项目复盘清单","description":"从目标、变量、筛选、交付和沉淀五个维度复盘 AI 视觉项目。","frontmatter":{"title":"AI 项目复盘清单","description":"从目标、变量、筛选、交付和沉淀五个维度复盘 AI 视觉项目。","pageClass":"page-resource-detail","status":"published"},"headers":[],"relativePath":"resources/notion.md","filePath":"resources/notion.md"}'),t={name:"resources/notion.md"};function o(s,a,n,h,u,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-项目复盘清单" tabindex="-1">AI 项目复盘清单 <a class="header-anchor" href="#ai-项目复盘清单" aria-label="Permalink to &quot;AI 项目复盘清单&quot;">​</a></h1><ul><li><strong>类型：</strong> 在线检查清单</li><li><strong>来源：</strong> Liuli AI Lab 自有整理</li><li><strong>授权：</strong> 可复制并按项目调整</li><li><strong>最后验证：</strong> 2026-07-11</li></ul><p>复盘不是记录“用了什么工具”，而是找出哪些判断可以被下一次项目复用。</p><h2 id="_1-目标" tabindex="-1">1. 目标 <a class="header-anchor" href="#_1-目标" aria-label="Permalink to &quot;1. 目标&quot;">​</a></h2><ul><li>最初要解决的业务问题是什么？</li><li>最终交付是否满足使用场景与尺寸要求？</li><li>哪些验收标准在项目中途发生了变化？</li></ul><h2 id="_2-变量" tabindex="-1">2. 变量 <a class="header-anchor" href="#_2-变量" aria-label="Permalink to &quot;2. 变量&quot;">​</a></h2><ul><li>哪些产品事实和品牌规则被固定？</li><li>哪些构图、风格、光线或材质变量被开放探索？</li><li>是否出现了无法复现的结果？原因是什么？</li></ul><h2 id="_3-筛选" tabindex="-1">3. 筛选 <a class="header-anchor" href="#_3-筛选" aria-label="Permalink to &quot;3. 筛选&quot;">​</a></h2><ul><li>入选方向满足了哪些标准？</li><li>被淘汰的方向失败在真实性、信息、审美还是成本？</li><li>哪些判断必须由设计师完成，不能交给生成模型？</li></ul><h2 id="_4-交付" tabindex="-1">4. 交付 <a class="header-anchor" href="#_4-交付" aria-label="Permalink to &quot;4. 交付&quot;">​</a></h2><ul><li>文件命名、尺寸、格式和版本是否统一？</li><li>接收方是否知道哪些文件可直接使用、哪些仍需确认？</li><li>是否记录了版权、授权或事实核验边界？</li></ul><h2 id="_5-沉淀" tabindex="-1">5. 沉淀 <a class="header-anchor" href="#_5-沉淀" aria-label="Permalink to &quot;5. 沉淀&quot;">​</a></h2><ul><li>哪些 Prompt 结构、参考图和参数值得保留？</li><li>哪些精修动作可以做成模板或检查项？</li><li>下一次相似项目可以直接从哪一步开始？</li></ul><h2 id="关联内容" tabindex="-1">关联内容 <a class="header-anchor" href="#关联内容" aria-label="Permalink to &quot;关联内容&quot;">​</a></h2><ul><li><a href="/aigc/commercial-visual-system.html">AI 商业视觉生产系统</a></li><li><a href="/portfolio/exhibition-visual.html">德国水处理展会视觉体系</a></li><li><a href="/blog/personal-resource-library.html">个人资源库比普通博客更重要</a></li></ul><p><a href="/resources/">← 返回资源库</a></p>',16)])])}const m=l(t,[["render",o]]);export{_ as __pageData,m as default};
